    'true'::jsonb,
    'test 271'
);
SELECT is(
    evaluate_json_logic('{"none":[{"var":"items"},{">=":[{"var":"qty"},1]}]}'::jsonb, '{"items":[]}'::jsonb),
    'true'::jsonb,
    'test 272'
);
