-- # String comparison (B20, B21): two strings compare as text in code-point order, as JavaScript does; a string against a number still coerces to a number
SELECT is(
    evaluate_json_logic('{">":["10","9"]}'::jsonb, '{}'::jsonb),
    'false'::jsonb,
    'test 291'
);
SELECT is(
    evaluate_json_logic('{"<":["10","9"]}'::jsonb, '{}'::jsonb),
    'true'::jsonb,
    'test 292'
);
